/// Read a standalone element of `diagram`, by its root. `None` if it is none of them.
// spec-audit: dgm:<colorsDef>
// spec-audit: dgm:<colorsDefHdr>
// spec-audit: dgm:<colorsDefHdrLst>
// spec-audit: dgm:<dataModel>
// spec-audit: dgm:<layoutDef>
// spec-audit: dgm:<layoutDefHdr>
// spec-audit: dgm:<layoutDefHdrLst>
// spec-audit: dgm:<relIds>
// spec-audit: dgm:<styleDef>
// spec-audit: dgm:<styleDefHdr>
// spec-audit: dgm:<styleDefHdrLst>
// spec-audit: x:drawing/2008/diagram:<drawing>
// spec-audit: x:drawing/2008/diagram:<dataModelExt>
// spec-audit: x:drawing/2010/diagram:<cNvPr>
// spec-audit: x:drawing/2010/diagram:<recolorImg>
// spec-audit: x:drawing/2016/11/diagram:<autoBuNodeInfoLst>
// spec-audit: x:drawing/2016/12/diagram:<spPr>
// spec-audit: x:drawing/2016/12/diagram:<lstStyle>
pub(crate) fn read_root(c: &mut SchemaReader<'_, '_>, el: &Elem) -> Res<Option<m::Root>> {
    if el.is(NS_DGM, "colorsDef") {
        return Ok(Some(m::Root::ColorsDef(Box::new(read_color_transform(
            c, el,
        )?))));
    }
    if el.is(NS_DGM, "colorsDefHdr") {
        return Ok(Some(m::Root::ColorsDefHdr(Box::new(
            read_color_transform_header(c, el)?,
        ))));
    }
    if el.is(NS_DGM, "colorsDefHdrLst") {
        return Ok(Some(m::Root::ColorsDefHdrLst(Box::new(
            read_color_transform_header_lst(c, el)?,
        ))));
    }
    if el.is(NS_DGM, "dataModel") {
        return Ok(Some(m::Root::DataModel(Box::new(read_data_model(c, el)?))));
    }
    if el.is(NS_DGM, "layoutDef") {
        return Ok(Some(m::Root::LayoutDef(Box::new(read_diagram_definition(
            c, el,
        )?))));
    }
    if el.is(NS_DGM, "layoutDefHdr") {
        return Ok(Some(m::Root::LayoutDefHdr(Box::new(
            read_diagram_definition_header(c, el)?,
        ))));
    }
    if el.is(NS_DGM, "layoutDefHdrLst") {
        return Ok(Some(m::Root::LayoutDefHdrLst(Box::new(
            read_diagram_definition_header_lst(c, el)?,
        ))));
    }
    if el.is(NS_DGM, "relIds") {
        return Ok(Some(m::Root::RelIds(Box::new(read_rel_ids(c, el)?))));
    }
    if el.is(NS_DGM, "styleDef") {
        return Ok(Some(m::Root::StyleDef(Box::new(read_style_definition(
            c, el,
        )?))));
    }
    if el.is(NS_DGM, "styleDefHdr") {
        return Ok(Some(m::Root::StyleDefHdr(Box::new(
            read_style_definition_header(c, el)?,
        ))));
    }
    if el.is(NS_DGM, "styleDefHdrLst") {
        return Ok(Some(m::Root::StyleDefHdrLst(Box::new(
            read_style_definition_header_lst(c, el)?,
        ))));
    }
    if el.is(NS_DSP, "drawing") {
        return Ok(Some(m::Root::DspDrawing(Box::new(read_dsp_drawing(
            c, el,
        )?))));
    }
    if el.is(NS_DSP, "dataModelExt") {
        return Ok(Some(m::Root::DspDataModelExt(Box::new(
            read_dsp_data_model_ext_block(c, el)?,
        ))));
    }
    if el.is(NS_DGM14, "cNvPr") {
        return Ok(Some(m::Root::Dgm14CNvPr(Box::new(read_identity(c, el)?))));
    }
    if el.is(NS_DGM14, "recolorImg") {
        return Ok(Some(m::Root::Dgm14RecolorImg(Box::new(
            read_dgm14_boolean(c, el)?,
        ))));
    }
    if el.is(NS_DGM1611, "autoBuNodeInfoLst") {
        return Ok(Some(m::Root::Dgm1611AutoBuNodeInfoLst(Box::new(
            read_dgm1611_number_diagram_info_list(c, el)?,
        ))));
    }
    if el.is(NS_DGM1612, "spPr") {
        return Ok(Some(m::Root::Dgm1612SpPr(Box::new(read_sp_pr(c, el)?))));
    }
    if el.is(NS_DGM1612, "lstStyle") {
        return Ok(Some(m::Root::Dgm1612LstStyle(Box::new(read_list_style(
            c, el,
        )?))));
    }
    Ok(None)
}

/// Whether an element is one that `read_root` reads.
pub fn is_root(el: &Elem) -> bool {
    el.is(NS_DGM, "colorsDef")
        || el.is(NS_DGM, "colorsDefHdr")
        || el.is(NS_DGM, "colorsDefHdrLst")
        || el.is(NS_DGM, "dataModel")
        || el.is(NS_DGM, "layoutDef")
        || el.is(NS_DGM, "layoutDefHdr")
        || el.is(NS_DGM, "layoutDefHdrLst")
        || el.is(NS_DGM, "relIds")
        || el.is(NS_DGM, "styleDef")
        || el.is(NS_DGM, "styleDefHdr")
        || el.is(NS_DGM, "styleDefHdrLst")
        || el.is(NS_DSP, "drawing")
        || el.is(NS_DSP, "dataModelExt")
        || el.is(NS_DGM14, "cNvPr")
        || el.is(NS_DGM14, "recolorImg")
        || el.is(NS_DGM1611, "autoBuNodeInfoLst")
        || el.is(NS_DGM1612, "spPr")
        || el.is(NS_DGM1612, "lstStyle")
}
